window.QUESTION_BANK={"1":{"folio":1,"section":"General Knowledge / Air Brake Test","questions":[{"n":1,"section":"General Knowledge / Air Brake Test","en":"You should try to park your vehicle so:","es":"Debe tratar de estacionar su vehículo de modo que:","optsEn":["You can pull forward when you leave.","There is at least one curb next to your vehicle.","Your vehicle is protected by trees or some other overhang."],"optsEs":["Pueda avanzar hacia adelante al salir.","Haya al menos una acera junto a su vehículo.","Su vehículo quede protegido por árboles u otro saliente."]},{"n":2,"section":"General Knowledge / Air Brake Test","en":"Controlled braking:","es":"El frenado controlado:","optsEn":["Involves locking the wheels for short periods of time.","Is used to keep a vehicle in a straight line when braking.","Should only be used with hydraulic brakes."],"optsEs":["Implica bloquear las ruedas por periodos cortos de tiempo.","Se usa para mantener el vehículo en línea recta al frenar.","Solo debe usarse con frenos hidráulicos."]},{"n":3,"section":"General Knowledge / Air Brake Test","en":"CDL medical certificates must be renewed every:","es":"Los certificados médicos CDL deben renovarse cada:","optsEn":["Year.","Two years.","Four years."],"optsEs":["Año.","Dos años.","Cuatro años."]},{"n":4,"section":"General Knowledge / Air Brake Test","en":"You are stopped. You want to start driving uphill. You should:","es":"Está detenido. Quiere comenzar a conducir cuesta arriba. Debe:","optsEn":["Partly engage the clutch and then release the parking brake.","Engage the clutch and accelerate quickly.","Keep the trailer brake hand valve applied until you reach 20 mph."],"optsEs":["Acoplar parcialmente el embrague y luego soltar el freno de estacionamiento.","Acoplar el embrague y acelerar rápidamente.","Mantener aplicada la válvula manual del freno del remolque hasta llegar a 20 mph."]},{"n":5,"section":"General Knowledge / Air Brake Test","en":"Which of these is not proper use of vehicle lights?","es":"¿Cuál de estos no es un uso adecuado de las luces del vehículo?","optsEn":["Turning on your headlights during the day when visibility is reduced.","Flashing your brake lights to warn someone behind you that you are slowing down.","Flashing your brake lights to stop someone tailgating."],"optsEs":["Encender los faros durante el día cuando la visibilidad es reducida.","Destellar las luces de freno para advertir a quien viene detrás que está desacelerando.","Destellar las luces de freno para detener a alguien que le sigue muy de cerca."]},{"n":6,"section":"General Knowledge / Air Brake Test","en":"Which of the following is not a type of retarder?","es":"¿Cuál de los siguientes no es un tipo de retardador?","optsEn":["Electric.","Hydraulic.","Robotic."],"optsEs":["Eléctrico.","Hidráulico.","Robótico."]},{"n":7,"section":"General Knowledge / Air Brake Test","en":"What is the first thing you should do if your brakes fail while driving downhill?","es":"¿Qué es lo primero que debe hacer si fallan los frenos mientras conduce cuesta abajo?","optsEn":["Call or radio for help.","Try to use your parking brake to stop.","Get off the road as soon as possible."],"optsEs":["Llamar o pedir ayuda por radio.","Intentar detenerse con el freno de estacionamiento.","Salir de la carretera lo antes posible."]},{"n":8,"section":"General Knowledge / Air Brake Test","en":"You are driving a 40 foot vehicle at 35 mph. The road is dry and visibility is good. What is the least amount of space you should keep in front of your vehicle to be safe?","es":"Conduce un vehículo de 40 pies a 35 mph. El camino está seco y la visibilidad es buena. ¿Cuál es el espacio mínimo que debe mantener delante de su vehículo para estar seguro?","optsEn":["3 seconds.","4 seconds.","5 seconds."],"optsEs":["3 segundos.","4 segundos.","5 segundos."]},{"n":9,"section":"General Knowledge / Air Brake Test","en":"When you drive in the mountains, you will have to use lower gears to drive safely down grades. Which of these does not affect your choice of gears?","es":"Al conducir en montaña deberá usar marchas más bajas para bajar pendientes con seguridad. ¿Cuál de estos no afecta su elección de marcha?","optsEn":["Weight of the load.","Tire tread type.","Length of the grade."],"optsEs":["El peso de la carga.","El tipo de dibujo de la llanta.","La longitud de la pendiente."]},{"n":10,"section":"General Knowledge / Air Brake Test","en":"When you must stop on a one-way or divided highway, you should place your reflective triangles at which of the following locations?","es":"Cuando deba detenerse en una carretera de un solo sentido o dividida, ¿en cuál de las siguientes ubicaciones debe colocar los triángulos reflectantes?","optsEn":["10 feet, 100 feet, and 500 feet toward approaching traffic.","10 feet, 100 feet, and 200 feet toward approaching traffic.","10 feet, 50 feet, and 100 feet toward approaching traffic."],"optsEs":["10 pies, 100 pies y 500 pies hacia el tráfico que se aproxima.","10 pies, 100 pies y 200 pies hacia el tráfico que se aproxima.","10 pies, 50 pies y 100 pies hacia el tráfico que se aproxima."]}]},"2":{"folio":3,"section":"General Knowledge Test","questions":[{"n":22,"section":"General Knowledge Test","en":"Which of the following may be a sign of tire failure?","es":"¿Cuál de los siguientes puede ser una señal de falla de una llanta?","optsEn":["A loud hissing noise.","Gentle thumping.","Wheels fishtailing."],"optsEs":["Un silbido fuerte.","Un golpeteo suave.","Las ruedas colean (fishtailing)."]},{"n":23,"section":"General Knowledge Test","en":"Which of these statements is not true?","es":"¿Cuál de estas afirmaciones no es verdadera?","optsEn":["Alcohol goes directly from the stomach to the blood stream.","A drinker can control how fast his or her body absorbs and gets rid of alcohol.","BAC is determined by how fast you drink, how much you drink, and how much you weigh."],"optsEs":["El alcohol pasa directamente del estómago al torrente sanguíneo.","Quien bebe puede controlar qué tan rápido su cuerpo absorbe y elimina el alcohol.","La concentración de alcohol en sangre depende de qué tan rápido bebe, cuánto bebe y cuánto pesa."]},{"n":24,"section":"General Knowledge Test","en":"Retarders:","es":"Los retardadores:","optsEn":["Allow you to disconnect the steering axle brakes.","Cannot be used on interstate highways.","Can cause the drive wheels to skid when they have poor traction."],"optsEs":["Permiten desconectar los frenos del eje de dirección.","No pueden usarse en carreteras interestatales.","Pueden hacer que las ruedas motrices patinen cuando tienen poca tracción."]},{"n":25,"section":"General Knowledge Test","en":"You are checking your brakes and suspension system during a pre-trip inspection. Which of these statements is true?","es":"Está revisando los frenos y el sistema de suspensión durante una inspección previa al viaje. ¿Cuál de estas afirmaciones es verdadera?","optsEn":["Just one missing leaf spring is not dangerous.","Cracked spring hangers that are still tight are not dangerous.","Brake shoes should not have oil, grease, or brake fluid on them."],"optsEs":["Que falte una sola hoja del muelle no es peligroso.","Los soportes del muelle agrietados pero aún apretados no son peligrosos.","Las zapatas de freno no deben tener aceite, grasa ni líquido de frenos."]},{"n":26,"section":"General Knowledge Test","en":"What should you do if a car coming toward you at night keeps its high beams on?","es":"¿Qué debe hacer si un auto que viene hacia usted de noche mantiene las luces altas encendidas?","optsEn":["Flash your high beams quickly at the other driver.","Look to the right edge of your lane or right side of the road.","Slow down and look straight ahead in your lane."],"optsEs":["Destellar rápidamente sus luces altas al otro conductor.","Mirar hacia el borde derecho de su carril o el lado derecho del camino.","Reducir la velocidad y mirar al frente dentro de su carril."]},{"n":27,"section":"General Knowledge Test","en":"Whenever you double your speed, it will take about _____ times as much distance to stop.","es":"Cada vez que duplica su velocidad, necesitará aproximadamente _____ veces más distancia para detenerse.","optsEn":["Two.","Three.","Four."],"optsEs":["Dos.","Tres.","Cuatro."]},{"n":28,"section":"General Knowledge Test","en":"What is the best advice for drivers to follow when a heavy fog occurs?","es":"¿Cuál es el mejor consejo que deben seguir los conductores cuando hay niebla densa?","optsEn":["Do not drive slowly, or other drivers may hit you.","Alternate your low and high beams to improve your vision.","Park at a rest area or truck stop until the fog has lifted."],"optsEs":["No conducir despacio, o los demás conductores podrían chocarlo.","Alternar las luces bajas y altas para mejorar la visión.","Estacionarse en un área de descanso o parada de camiones hasta que la niebla se disipe."]},{"n":29,"section":"General Knowledge Test","en":"If a straight vehicle (no trailer or articulation) goes into a front-wheel skid, it will:","es":"Si un vehículo rígido (sin remolque ni articulación) entra en un derrape de las ruedas delanteras:","optsEn":["Slide sideways and spin out.","Travel straight ahead even if you turn the steering wheel.","Travel straight ahead until you turn the steering wheel."],"optsEs":["Se deslizará de lado y girará sin control.","Seguirá derecho aunque gire el volante.","Seguirá derecho hasta que gire el volante."]},{"n":30,"section":"General Knowledge Test","en":"Which of these statements is true about transported hazardous materials?","es":"¿Cuál de estas afirmaciones es verdadera sobre el transporte de materiales peligrosos?","optsEn":["Hazardous materials can be a risk to health and safety.","All trucks with any amount of hazardous materials must display placards.","All public roads allow properly loaded trucks to carry hazardous materials."],"optsEs":["Los materiales peligrosos pueden ser un riesgo para la salud y la seguridad.","Todo camión con cualquier cantidad de material peligroso debe llevar rótulos.","Todas las vías públicas permiten que camiones bien cargados transporten materiales peligrosos."]},{"n":31,"section":"General Knowledge Test","en":"When do strong winds affect driving the most?","es":"¿Cuándo afectan más los vientos fuertes a la conducción?","optsEn":["On open highways.","On bridges or overpasses.","When exiting tunnels."],"optsEs":["En carreteras abiertas.","En puentes o pasos elevados.","Al salir de túneles."]},{"n":32,"section":"General Knowledge Test","en":"Optional safety equipment may include emergency phone numbers, tire chains, and:","es":"El equipo de seguridad opcional puede incluir números de teléfono de emergencia, cadenas para llantas y:","optsEn":["Tire changing equipment.","Red reflective triangles.","Charged fire extinguisher."],"optsEs":["Equipo para cambiar llantas.","Triángulos reflectantes rojos.","Un extintor cargado."]}]},"3":{"folio":5,"section":"General Knowledge Test","questions":[{"n":43,"section":"General Knowledge Test","en":"You wish to turn right from a two-lane, two-way street into another. Your vehicle is so long that you must swing wide to complete the turn. Which of these figures shows how you should make the turn?","es":"Desea girar a la derecha de una calle de dos carriles y doble sentido hacia otra. Su vehículo es tan largo que debe abrirse para completar el giro. ¿Cuál de estas figuras muestra cómo debe hacer el giro?","optsEn":["Figure A.","Figure B.","Figure C."],"optsEs":["Figura A.","Figura B.","Figura C."],"figure":true},{"n":44,"section":"General Knowledge Test","en":"Which of these is a good thing to do when you steer to avoid a crash?","es":"¿Cuál de estas es una buena práctica al girar para evitar un choque?","optsEn":["Don't turn the steering wheel any more than needed.","Avoid counter steering.","Apply the brakes while turning."],"optsEs":["No girar el volante más de lo necesario.","Evitar el contravolanteo.","Aplicar los frenos mientras gira."]},{"n":45,"section":"General Knowledge Test","en":"If you must drive into the oncoming lane to turn, you should:","es":"Si debe invadir el carril contrario para girar, debe:","optsEn":["Allow enough space to get completely across the intersection.","Back up to allow oncoming traffic to pass.","Complete your turn without stopping."],"optsEs":["Dejar espacio suficiente para cruzar por completo la intersección.","Retroceder para dejar pasar al tráfico que viene de frente.","Completar el giro sin detenerse."]},{"n":46,"section":"General Knowledge Test","en":"Which of these statements is not true about engine belts in hot weather?","es":"¿Cuál de estas afirmaciones no es verdadera sobre las bandas del motor en clima caluroso?","optsEn":["Cracking is likely to occur but is not a safety threat.","You can check the tightness of the belts by pressing on them.","Loose belts will not turn the water pump and/or fan on properly."],"optsEs":["El agrietamiento es probable pero no representa un riesgo de seguridad.","Puede comprobar la tensión de las bandas presionándolas.","Las bandas flojas no harán girar correctamente la bomba de agua ni el ventilador."]},{"n":47,"section":"General Knowledge Test","en":"The best drivers are those who watch and prepare for hazards. This is called being:","es":"Los mejores conductores son los que observan y se preparan ante los peligros. A esto se le llama ser:","optsEn":["Offensive.","Defensive.","Objective."],"optsEs":["Ofensivo.","Defensivo.","Objetivo."]},{"n":48,"section":"General Knowledge Test","en":"What will help keep an engine cool in hot weather?","es":"¿Qué ayuda a mantener frío el motor en clima caluroso?","optsEn":["Driving faster to force more air into the radiator.","Running the air conditioner.","Making sure the engine has the right amount of oil."],"optsEs":["Conducir más rápido para forzar más aire al radiador.","Encender el aire acondicionado.","Asegurarse de que el motor tenga la cantidad correcta de aceite."]},{"n":49,"section":"General Knowledge Test","en":"How far should a driver look ahead of the vehicle while driving?","es":"¿Qué tan lejos debe mirar un conductor por delante del vehículo mientras conduce?","optsEn":["1-2 seconds.","5-8 seconds.","12-15 seconds."],"optsEs":["1-2 segundos.","5-8 segundos.","12-15 segundos."]},{"n":50,"section":"General Knowledge Test","en":"You are checking your tires during a pre-trip inspection. Which of these statements is true?","es":"Está revisando las llantas durante una inspección previa al viaje. ¿Cuál de estas afirmaciones es verdadera?","optsEn":["Tires of mismatched sizes should not be used on the same vehicle.","Radial and bias-ply tires can be used together on the same vehicle.","2-32 inch tread depth is safe for the front tires."],"optsEs":["No deben usarse llantas de tamaños distintos en el mismo vehículo.","Las llantas radiales y de capas diagonales pueden usarse juntas en el mismo vehículo.","Una profundidad de dibujo de 2/32 de pulgada es segura para las llantas delanteras."]},{"n":1,"section":"Air Brake Test","en":"The most important thing to do when a low air pressure warning comes on is:","es":"Lo más importante que debe hacer cuando se enciende la advertencia de baja presión de aire es:","optsEn":["Up shift and drive to a safe place.","Downshift and drive to a safe place.","Stop and safely park as soon as possible."],"optsEs":["Subir de marcha y conducir hasta un lugar seguro.","Bajar de marcha y conducir hasta un lugar seguro.","Detenerse y estacionarse con seguridad lo antes posible."]}]},"4":{"folio":7,"section":"Air Brake Test","questions":[{"n":14,"section":"Air Brake Test","en":"The safety valve is usually set to reduce air pressure at _____ psi.","es":"La válvula de seguridad normalmente está ajustada para liberar presión de aire a _____ psi.","optsEn":["50.","100.","150."],"optsEs":["50.","100.","150."]},{"n":15,"section":"Air Brake Test","en":"The air compressor should stop pumping at about _____ psi.","es":"El compresor de aire debe dejar de bombear aproximadamente a _____ psi.","optsEn":["100.","125.","150."],"optsEs":["100.","125.","150."]},{"n":16,"section":"Air Brake Test","en":"What is emergency stab braking?","es":"¿Qué es el frenado de emergencia tipo “stab”?","optsEn":["Press hard on the brake and apply full hand valve until you stop.","Use light steady pressure on the brake pedal.","Brake hard, release the brakes when the wheels lock, and reapply the brakes when the wheels start rolling."],"optsEs":["Pisar fuerte el freno y aplicar la válvula manual a fondo hasta detenerse.","Aplicar presión ligera y constante sobre el pedal del freno.","Frenar fuerte, soltar los frenos cuando las ruedas se bloqueen y volver a aplicarlos cuando las ruedas empiecen a rodar."]},{"n":17,"section":"Air Brake Test","en":"Your vehicle has a dual air brake system. If a low air pressure warning comes on for the secondary system, you should:","es":"Su vehículo tiene un sistema doble de frenos de aire. Si se enciende la advertencia de baja presión del sistema secundario, debe:","optsEn":["Stop the vehicle and continue only when the system is fixed.","Reduce your speed, and test the remaining system while driving.","Reduce your speed, and drive to the nearest garage for repairs."],"optsEs":["Detener el vehículo y continuar solo cuando el sistema esté reparado.","Reducir la velocidad y probar el sistema restante mientras conduce.","Reducir la velocidad y conducir al taller más cercano para repararlo."]},{"n":18,"section":"Air Brake Test","en":"All air brake equipped vehicles have:","es":"Todos los vehículos equipados con frenos de aire tienen:","optsEn":["An air supply pressure gauge.","An air use gauge.","A backup hydraulic system."],"optsEs":["Un medidor de presión del suministro de aire.","Un medidor de consumo de aire.","Un sistema hidráulico de respaldo."]},{"n":19,"section":"Air Brake Test","en":"When you apply the brakes, the brake shoes/linings are pressed against the:","es":"Cuando aplica los frenos, las zapatas o balatas se presionan contra:","optsEn":["Brake drum or disc.","Slack adjuster.","S-cam."],"optsEs":["El tambor o disco de freno.","El ajustador de holgura.","La leva en S."]},{"n":20,"section":"Air Brake Test","en":"If your truck's air compressor has its own oil supply, when should you first check the oil level?","es":"Si el compresor de aire de su camión tiene su propio suministro de aceite, ¿cuándo debe revisar el nivel de aceite por primera vez?","optsEn":["Before driving.","During your first en route inspection.","Immediately after you stop driving."],"optsEs":["Antes de conducir.","Durante la primera inspección en ruta.","Inmediatamente después de dejar de conducir."]}]},"5":{"folio":9,"section":"General Knowledge Test","questions":[{"n":9,"section":"General Knowledge Test","en":"In your mirror, you see a car approaching from the rear. The next time you check your mirror, you don't see the car. To change lanes, you should:","es":"En el espejo ve un auto que se acerca por detrás. La siguiente vez que mira el espejo, ya no lo ve. Para cambiar de carril debe:","optsEn":["Wait until you are sure the car isn't in your blind spot.","Ease into the other lane slowly so the car can get out of your way.","Assume the car left the road and change lanes as normal."],"optsEs":["Esperar hasta estar seguro de que el auto no está en su punto ciego.","Entrar despacio al otro carril para que el auto pueda apartarse.","Suponer que el auto salió de la carretera y cambiar de carril con normalidad."]},{"n":10,"section":"General Knowledge Test","en":"When driving in cold weather, your tire tread should:","es":"Al conducir en clima frío, el dibujo de sus llantas debe:","optsEn":["Be checked every 100 miles or every two hours.","Be double the depth required in normal weather.","Provide enough traction to steer and push the vehicle through snow."],"optsEs":["Revisarse cada 100 millas o cada dos horas.","Tener el doble de profundidad que en clima normal.","Dar tracción suficiente para dirigir y empujar el vehículo por la nieve."]},{"n":11,"section":"General Knowledge Test","en":"Which of the following is not characteristic of a front tire failure?","es":"¿Cuál de los siguientes no es característico de la falla de una llanta delantera?","optsEn":["Steering wheel twisting.","Vehicle fishtail.","Difficult steering."],"optsEs":["El volante se tuerce.","El vehículo colea.","Dirección difícil."]},{"n":12,"section":"General Knowledge Test","en":"Whenever you double your speed, your vehicle has about ____ times the destructive power if it crashes.","es":"Cada vez que duplica su velocidad, su vehículo tiene aproximadamente ____ veces el poder destructivo si choca.","optsEn":["Two.","Three.","Four."],"optsEs":["Dos.","Tres.","Cuatro."]},{"n":13,"section":"General Knowledge Test","en":"You can see this sign on a vehicle ahead of you. What does the sign mean?","es":"Ve este letrero en un vehículo delante de usted. ¿Qué significa?","optsEn":["Slow moving vehicle.","Hazardous materials on board.","Student driver."],"optsEs":["Vehículo de movimiento lento.","Materiales peligrosos a bordo.","Conductor en formación."],"figure":true},{"n":14,"section":"General Knowledge Test","en":"Backing a commercial vehicle is:","es":"Retroceder con un vehículo comercial es:","optsEn":["Not dangerous if you have a helper.","Not dangerous if you do not have to turn.","Always dangerous."],"optsEs":["No peligroso si tiene un ayudante.","No peligroso si no tiene que girar.","Siempre peligroso."]},{"n":15,"section":"General Knowledge Test","en":"Most serious skids result from:","es":"La mayoría de los derrapes graves son consecuencia de:","optsEn":["Turning too sharply.","Decelerating too fast.","Driving too fast for conditions."],"optsEs":["Girar demasiado cerrado.","Desacelerar demasiado rápido.","Conducir demasiado rápido para las condiciones."]},{"n":16,"section":"General Knowledge Test","en":"You do not have a HAZMAT endorsement on your commercial driver license. You may drive a vehicle transporting hazardous materials when:","es":"No tiene el endoso HAZMAT en su licencia de conducir comercial. Puede conducir un vehículo que transporte materiales peligrosos cuando:","optsEn":["The GVWR is 26,001 pounds or less.","The vehicle does not require placards.","A person with a HAZMAT endorsement rides with you."],"optsEs":["El peso bruto vehicular sea de 26,001 libras o menos.","El vehículo no requiera rótulos.","Viaje con usted una persona con endoso HAZMAT."]},{"n":17,"section":"General Knowledge Test","en":"If your brakes get wet while driving on a rainy day, what can happen when you apply the brakes?","es":"Si los frenos se mojan mientras conduce en un día lluvioso, ¿qué puede ocurrir al aplicarlos?","optsEn":["Hydroplaning.","Excessive brake wear.","Trailer jackknife."],"optsEs":["Hidroplaneo.","Desgaste excesivo de los frenos.","Tijereteo del remolque."]},{"n":18,"section":"General Knowledge Test","en":"What is the proper way to hold a steering wheel?","es":"¿Cuál es la forma correcta de sujetar el volante?","optsEn":["Both hands close together, near the top of the wheel.","Both hands close together, near the bottom of the wheel.","Both hands, on opposite sides of the wheel."],"optsEs":["Ambas manos juntas, cerca de la parte superior del volante.","Ambas manos juntas, cerca de la parte inferior del volante.","Ambas manos en lados opuestos del volante."]},{"n":19,"section":"General Knowledge Test","en":"Which of these statements is true about mirror adjustment?","es":"¿Cuál de estas afirmaciones es verdadera sobre el ajuste de los espejos?","optsEn":["You should adjust your mirrors before you start a trip.","The mirrors can be adjusted correctly even if the trailer is not straight.","You can adjust the mirrors while you are driving."],"optsEs":["Debe ajustar los espejos antes de comenzar el viaje.","Los espejos pueden ajustarse correctamente aunque el remolque no esté alineado.","Puede ajustar los espejos mientras conduce."]},{"n":20,"section":"General Knowledge Test","en":"What should you do if you are not sure if you have enough overhead clearance?","es":"¿Qué debe hacer si no está seguro de tener suficiente espacio libre por encima?","optsEn":["Slow down slightly and try to drive under the object.","Find another route that will not require driving under the object.","Estimate the height of an overhead object if it is not posted."],"optsEs":["Reducir un poco la velocidad e intentar pasar por debajo del objeto.","Buscar otra ruta que no requiera pasar por debajo del objeto.","Estimar la altura del objeto elevado si no está señalizada."]}]},"6":{"folio":11,"section":"General Knowledge Test","questions":[{"n":33,"section":"General Knowledge Test","en":"The purpose of a retarder is to:","es":"El propósito de un retardador es:","optsEn":["Apply extra braking power to the non-drive axles.","Help prevent skids and reduce brake wear.","Help slow the vehicle while driving and reduce brake wear."],"optsEs":["Aplicar potencia de frenado adicional a los ejes no motrices.","Ayudar a evitar derrapes y reducir el desgaste de los frenos.","Ayudar a frenar el vehículo mientras conduce y reducir el desgaste de los frenos."]},{"n":34,"section":"General Knowledge Test","en":"You should signal continuously while turning because:","es":"Debe mantener la señal encendida durante todo el giro porque:","optsEn":["You need both hands on the steering wheel to turn safely.","It is illegal to turn off your signal before completing a turn.","Most vehicles have self-canceling signals."],"optsEs":["Necesita ambas manos en el volante para girar con seguridad.","Es ilegal apagar la señal antes de completar el giro.","La mayoría de los vehículos tiene señales que se cancelan solas."]},{"n":35,"section":"General Knowledge Test","en":"Why is a broken exhaust system dangerous?","es":"¿Por qué es peligroso un sistema de escape roto?","optsEn":["Poisonous fumes could enter the cab or sleeper berth.","You could pollute the air with exhaust smoke.","Loud noise could damage the driver's ears."],"optsEs":["Gases venenosos podrían entrar a la cabina o al camarote.","Podría contaminar el aire con humo del escape.","El ruido fuerte podría dañar los oídos del conductor."]},{"n":36,"section":"General Knowledge Test","en":"You are checking your steering and exhaust systems in a pre-trip inspection. Which of these problems should be fixed before the vehicle is driven?","es":"Está revisando la dirección y el escape en una inspección previa al viaje. ¿Cuál de estos problemas debe repararse antes de conducir el vehículo?","optsEn":["Oil on the tie rod.","Gray smoke from the exhaust.","Steering wheel play — more than 10° (2 inches on a 20-inch wheel)."],"optsEs":["Aceite en la barra de dirección.","Humo gris del escape.","Juego del volante mayor a 10° (2 pulgadas en un volante de 20 pulgadas)."]},{"n":37,"section":"General Knowledge Test","en":"Which of these statements is true about double clutching and shifting?","es":"¿Cuál de estas afirmaciones es verdadera sobre el doble embrague y los cambios?","optsEn":["Double clutching should not be used when the road is slippery.","Double clutching should only be used with a heavy load.","You can use the tachometer to tell you when to shift."],"optsEs":["No debe usarse doble embrague cuando el camino está resbaloso.","El doble embrague solo debe usarse con carga pesada.","Puede usar el tacómetro para saber cuándo cambiar de marcha."]},{"n":38,"section":"General Knowledge Test","en":"CDL medical certificates must be renewed every:","es":"Los certificados médicos CDL deben renovarse cada:","optsEn":["Year.","Two years.","Four years."],"optsEs":["Año.","Dos años.","Cuatro años."]},{"n":39,"section":"General Knowledge Test","en":"You are driving a new truck with a manual transmission. What gear will you probably have to use to take a long, steep, downhill grade?","es":"Conduce un camión nuevo con transmisión manual. ¿Qué marcha tendrá que usar probablemente para bajar una pendiente larga y empinada?","optsEn":["The same gear you would use to climb the hill.","A higher gear than you would use to climb the hill.","A lower gear than you would use to climb the hill."],"optsEs":["La misma marcha que usaría para subir la cuesta.","Una marcha más alta que la que usaría para subir la cuesta.","Una marcha más baja que la que usaría para subir la cuesta."]},{"n":40,"section":"General Knowledge Test","en":"You are starting your vehicle in motion from a stop. As you apply power to the drive wheels, they start to spin. You should:","es":"Está poniendo el vehículo en marcha desde una parada. Al aplicar potencia a las ruedas motrices, estas empiezan a patinar. Debe:","optsEn":["Take your foot off the accelerator.","Take your foot off the accelerator and apply the brakes.","Try a lower gear."],"optsEs":["Quitar el pie del acelerador.","Quitar el pie del acelerador y aplicar los frenos.","Probar una marcha más baja."]},{"n":41,"section":"General Knowledge Test","en":"Why will your vehicle's speed naturally increase on downgrades?","es":"¿Por qué aumenta naturalmente la velocidad de su vehículo en las bajadas?","optsEn":["The engine runs smoother.","Gravity.","Lack of traction."],"optsEs":["El motor funciona más suave.","La gravedad.","La falta de tracción."]},{"n":42,"section":"General Knowledge Test","en":"Stab braking:","es":"El frenado tipo “stab”:","optsEn":["Involves applying the brakes and then releasing them after the wheels lock up.","Should be used on vehicles without antilock brake systems.","Should only be used with hydraulic brakes."],"optsEs":["Consiste en aplicar los frenos y luego soltarlos después de que las ruedas se bloquean.","Debe usarse en vehículos sin sistema antibloqueo de frenos.","Solo debe usarse con frenos hidráulicos."]},{"n":43,"section":"General Knowledge Test","en":"You must complete a written vehicle inspection report each day. You must sign the report:","es":"Debe completar un informe escrito de inspección del vehículo cada día. Debe firmar el informe:","optsEn":["If the previous driver noted any defects.","Only when defects are noted that are certified to be repaired.","Only when the noted defects are certified not needing repair."],"optsEs":["Si el conductor anterior anotó algún defecto.","Solo cuando se anoten defectos que se certifiquen como reparados.","Solo cuando los defectos anotados se certifiquen como que no requieren reparación."]},{"n":44,"section":"General Knowledge Test","en":"Placards must be:","es":"Los rótulos deben:","optsEn":["Displayed on all vehicles transporting any amount of hazardous materials.","Placed only on the front and rear of a vehicle.","Placed on all four sides of a vehicle."],"optsEs":["Mostrarse en todo vehículo que transporte cualquier cantidad de materiales peligrosos.","Colocarse solo en el frente y la parte trasera del vehículo.","Colocarse en los cuatro lados del vehículo."]}]},"7":{"folio":13,"section":"Air Brake Test","questions":[{"n":3,"section":"Air Brake Test","en":"If the spring brakes are on, when should you push the brake pedal?","es":"Si los frenos de resorte están aplicados, ¿cuándo debe pisar el pedal del freno?","optsEn":["Only when driving down a hill.","Only on slippery roads.","Never."],"optsEs":["Solo al bajar una cuesta.","Solo en caminos resbalosos.","Nunca."]},{"n":4,"section":"Air Brake Test","en":"The braking power of the spring brakes:","es":"La potencia de frenado de los frenos de resorte:","optsEn":["Depends on the service brakes being in adjustment.","Is not affected by the condition of the service brakes.","Can only be tested by highly-trained brake service people."],"optsEs":["Depende de que los frenos de servicio estén bien ajustados.","No se ve afectada por el estado de los frenos de servicio.","Solo puede probarla personal de frenos altamente capacitado."]},{"n":5,"section":"Air Brake Test","en":"If your truck has a dual air system and one of the systems is low on pressure:","es":"Si su camión tiene un sistema doble de aire y uno de los sistemas tiene baja presión:","optsEn":["The brake drums will not be fully pressurized.","Either the front or rear brakes will not be fully operational.","The manual slack adjuster on the S-cam brakes are not set properly."],"optsEs":["Los tambores de freno no estarán completamente presurizados.","Los frenos delanteros o los traseros no funcionarán por completo.","El ajustador manual de holgura de los frenos de leva en S no está bien ajustado."]},{"n":6,"section":"Air Brake Test","en":"In air brake vehicles, the parking brakes should be used:","es":"En vehículos con frenos de aire, los frenos de estacionamiento deben usarse:","optsEn":["As little as possible.","To hold your speed when going downhill.","Any time the vehicle is parked."],"optsEs":["Lo menos posible.","Para mantener la velocidad al bajar una cuesta.","Siempre que el vehículo esté estacionado."]},{"n":7,"section":"Air Brake Test","en":"You should know your brakes are fading when:","es":"Debe saber que sus frenos están perdiendo eficacia cuando:","optsEn":["You have to push the brake pedal harder to control speed on a downgrade.","The brake pedal feels \"spongy\" when you apply pressure.","Your speed increases when you reduce pressure on your brake pedal."],"optsEs":["Tiene que pisar el pedal con más fuerza para controlar la velocidad en una bajada.","El pedal se siente “esponjoso” al aplicar presión.","Su velocidad aumenta cuando reduce la presión sobre el pedal."]},{"n":8,"section":"Air Brake Test","en":"Truck and bus parking or emergency brakes must be held on by:","es":"Los frenos de estacionamiento o de emergencia de camiones y autobuses deben mantenerse aplicados mediante:","optsEn":["Air pressure.","A modulating control valve.","Mechanical force."],"optsEs":["Presión de aire.","Una válvula de control moduladora.","Fuerza mecánica."]},{"n":9,"section":"Air Brake Test","en":"The air loss rate for a straight truck or bus with the engine off and the brakes on should not be more than:","es":"La pérdida de aire en un camión rígido o autobús con el motor apagado y los frenos aplicados no debe ser mayor de:","optsEn":["1 psi in one minute.","2 psi in 45 seconds.","3 psi in one minute."],"optsEs":["1 psi en un minuto.","2 psi en 45 segundos.","3 psi en un minuto."]},{"n":10,"section":"Air Brake Test","en":"The most common type of foundation brake found on heavy vehicles is the:","es":"El tipo de freno de base más común en vehículos pesados es el:","optsEn":["Wedge drum.","S-cam drum.","Disc brake."],"optsEs":["Tambor de cuña.","Tambor de leva en S.","Freno de disco."]},{"n":11,"section":"Air Brake Test","en":"The stop light switch:","es":"El interruptor de las luces de freno:","optsEn":["Turns on the brake lights to warn drivers behind you.","Tells you when you need to use your emergency brakes.","Tells you when the air brake system is low on air pressure."],"optsEs":["Enciende las luces de freno para advertir a los conductores detrás de usted.","Le indica cuándo necesita usar los frenos de emergencia.","Le indica cuándo el sistema de frenos de aire tiene baja presión."]},{"n":12,"section":"Air Brake Test","en":"The brake pedal in an air brake system:","es":"El pedal del freno en un sistema de frenos de aire:","optsEn":["Controls the speed of the air compressor.","Controls the air pressure applied to put on the brakes.","Is connected to slack adjusters by a series of rods and linkages."],"optsEs":["Controla la velocidad del compresor de aire.","Controla la presión de aire aplicada para accionar los frenos.","Está conectado a los ajustadores de holgura mediante varillas y articulaciones."]},{"n":13,"section":"Air Brake Test","en":"The air compressor governor controls:","es":"El gobernador del compresor de aire controla:","optsEn":["When air is pumped into the air tanks.","The speed of the air compressor.","Air pressure applied to the brakes."],"optsEs":["Cuándo se bombea aire a los tanques.","La velocidad del compresor de aire.","La presión de aire aplicada a los frenos."]},{"n":14,"section":"Air Brake Test","en":"The air brake lag distance at 55 mph on dry pavement adds about ____ feet to your stopping distance.","es":"El retraso de los frenos de aire a 55 mph sobre pavimento seco añade unos ____ pies a su distancia de frenado.","optsEn":["12.","32.","52."],"optsEs":["12.","32.","52."]}]},"8":{"folio":15,"section":"General Knowledge Test","questions":[{"n":1,"section":"General Knowledge Test","en":"When the roads are slippery, you should:","es":"Cuando los caminos están resbalosos, debe:","optsEn":["Make turns as carefully as possible.","Stop and test tire traction while going up hills.","Decrease the distance that you look ahead of your vehicle."],"optsEs":["Tomar las curvas con el mayor cuidado posible.","Detenerse y probar la tracción de las llantas al subir cuestas.","Reducir la distancia a la que mira por delante del vehículo."]},{"n":2,"section":"General Knowledge Test","en":"Which statement is true?","es":"¿Cuál afirmación es verdadera?","optsEn":["Most people are more alert at night than during the day.","Most hazards are easier to see at night than during the day.","Many heavy vehicle accidents occur between midnight and 6am."],"optsEs":["La mayoría de la gente está más alerta de noche que de día.","La mayoría de los peligros se ven más fácil de noche que de día.","Muchos accidentes de vehículos pesados ocurren entre la medianoche y las 6 a. m."]},{"n":3,"section":"General Knowledge Test","en":"Where must you keep shipping papers when transporting hazardous materials?","es":"¿Dónde debe llevar los documentos de embarque al transportar materiales peligrosos?","optsEn":["Under the driver's seat.","In a pouch on the driver's door or on the seat.","In the glove compartment, which must be locked."],"optsEs":["Debajo del asiento del conductor.","En una bolsa en la puerta del conductor o sobre el asiento.","En la guantera, que debe estar cerrada con llave."]},{"n":4,"section":"General Knowledge Test","en":"You should use your mirrors to check:","es":"Debe usar los espejos para comprobar:","optsEn":["If your running lights are working properly.","Blind spots only.","Where the rear of your vehicle is while you make turns."],"optsEs":["Si las luces de posición funcionan correctamente.","Únicamente los puntos ciegos.","Dónde está la parte trasera de su vehículo mientras gira."]},{"n":5,"section":"General Knowledge Test","en":"Which of these statements is true about cargo types?","es":"¿Cuál de estas afirmaciones es verdadera sobre los tipos de carga?","optsEn":["Unstable loads (i.e., hanging meat, livestock) require extra caution on curves.","Oversize loads can be transported without special permits when roadways are not busy.","Tank vehicles used to transport liquids should always be fully loaded."],"optsEs":["Las cargas inestables (carne colgada, ganado) exigen precaución adicional en las curvas.","Las cargas de sobredimensión pueden transportarse sin permisos especiales cuando hay poco tráfico.","Los vehículos cisterna que transportan líquidos siempre deben ir completamente llenos."]},{"n":6,"section":"General Knowledge Test","en":"You are driving a 40 foot vehicle at 35 mph. The road is dry and visibility is good. What is the least amount of space that you should keep in front of your vehicle to be safe?","es":"Conduce un vehículo de 40 pies a 35 mph. El camino está seco y la visibilidad es buena. ¿Cuál es el espacio mínimo que debe mantener delante de su vehículo para estar seguro?","optsEn":["3 seconds.","4 seconds.","5 seconds."],"optsEs":["3 segundos.","4 segundos.","5 segundos."]},{"n":7,"section":"General Knowledge Test","en":"If you're not sure how to put out a hazardous materials fire, you should:","es":"Si no está seguro de cómo apagar un incendio de materiales peligrosos, debe:","optsEn":["Use water.","Use dirt.","Wait for qualified fire fighters."],"optsEs":["Usar agua.","Usar tierra.","Esperar a bomberos capacitados."]},{"n":8,"section":"General Knowledge Test","en":"According to the Commercial Driver Handbook, why should you limit the use of your horn?","es":"Según el Manual del Conductor Comercial, ¿por qué debe limitar el uso del claxon?","optsEn":["It can startle other drivers.","It reduces air pressure needed to stop vehicles with air brakes.","You should keep both hands on the steering wheel at all times."],"optsEs":["Puede sobresaltar a otros conductores.","Reduce la presión de aire necesaria para detener vehículos con frenos de aire.","Debe mantener ambas manos en el volante en todo momento."]},{"n":9,"section":"General Knowledge Test","en":"Take extra care to keep your vehicle centered in your lane because commercial vehicles:","es":"Ponga especial cuidado en mantener su vehículo centrado en el carril porque los vehículos comerciales:","optsEn":["Are often wider than other vehicles.","Tend to sway from side to side.","Require a lot of room to change lanes."],"optsEs":["Suelen ser más anchos que otros vehículos.","Tienden a balancearse de lado a lado.","Requieren mucho espacio para cambiar de carril."]}]},"9":{"folio":17,"section":"General Knowledge Test","questions":[{"n":21,"section":"General Knowledge Test","en":"If you need to leave the road in a traffic emergency, you should:","es":"Si necesita salir de la carretera en una emergencia de tráfico, debe:","optsEn":["Try to get all wheels off the pavement.","Avoid braking until your speed has dropped to about 20 mph.","Avoid driving on the shoulder of the road."],"optsEs":["Intentar sacar todas las ruedas del pavimento.","Evitar frenar hasta que la velocidad baje a unas 20 mph.","Evitar conducir sobre el acotamiento."]},{"n":23,"section":"General Knowledge Test","en":"Which of these is usually true about driving in tunnels?","es":"¿Cuál de estas suele ser cierta al conducir en túneles?","optsEn":["Headlights are required by law.","There may be strong winds when exiting.","Speeds are limited to 30 mph or less."],"optsEs":["Los faros son obligatorios por ley.","Puede haber vientos fuertes al salir.","Las velocidades se limitan a 30 mph o menos."]},{"n":24,"section":"General Knowledge Test","en":"Which of these items is not checked in a pre-trip inspection?","es":"¿Cuál de estos elementos no se revisa en una inspección previa al viaje?","optsEn":["Vehicle lights.","Cargo securement.","Fuel level."],"optsEs":["Las luces del vehículo.","La sujeción de la carga.","El nivel de combustible."]},{"n":25,"section":"General Knowledge Test","en":"What three things add up to the total stopping distance for your truck or bus?","es":"¿Qué tres factores suman la distancia total de frenado de su camión o autobús?","optsEn":["Attention distance, reaction distance, slowing distance.","Observation distance, response distance, braking distance.","Perception distance, reaction distance, braking distance."],"optsEs":["Distancia de atención, distancia de reacción, distancia de desaceleración.","Distancia de observación, distancia de respuesta, distancia de frenado.","Distancia de percepción, distancia de reacción, distancia de frenado."]},{"n":26,"section":"General Knowledge Test","en":"Which of these is not a good rule to follow when caring for an injured person at an accident scene?","es":"¿Cuál de estas no es una buena regla al atender a una persona herida en el lugar de un accidente?","optsEn":["If a qualified person is helping them, stay out of the way unless asked to help.","Move severely injured persons if a danger exists.","Keep injured persons cool."],"optsEs":["Si una persona capacitada la está atendiendo, no estorbe salvo que le pidan ayuda.","Mover a los heridos graves si existe un peligro.","Mantener frescos a los heridos."]},{"n":27,"section":"General Knowledge Test","en":"Which of these happens when a tire blows out at highway speeds?","es":"¿Cuál de estas ocurre cuando una llanta revienta a velocidad de carretera?","optsEn":["A vibrating feeling.","A hissing sound.","A rapid drop in speed to less than 20 mph."],"optsEs":["Una sensación de vibración.","Un silbido.","Una caída rápida de la velocidad a menos de 20 mph."]},{"n":28,"section":"General Knowledge Test","en":"You are checking your steering and exhaust systems in a pre-trip inspection. Which of these problems should be fixed before the vehicle is driven?","es":"Está revisando la dirección y el escape en una inspección previa al viaje. ¿Cuál de estos problemas debe repararse antes de conducir el vehículo?","optsEn":["Oil on the tie rod.","Black smoke from the exhaust pipe.","Steering wheel play of more than 10 degrees (2 inches on a 20-inch steering wheel)."],"optsEs":["Aceite en la barra de dirección.","Humo negro del tubo de escape.","Juego del volante mayor a 10 grados (2 pulgadas en un volante de 20 pulgadas)."]},{"n":29,"section":"General Knowledge Test","en":"Which of these is true about a vehicle's overhead clearance?","es":"¿Cuál de estas es verdadera sobre el espacio libre superior de un vehículo?","optsEn":["Pavement does not affect the clearance height under bridges or overpasses.","Cargo weight can change your vehicle's height.","Warnings are always posted for low clearance areas."],"optsEs":["El pavimento no afecta la altura libre bajo puentes o pasos elevados.","El peso de la carga puede cambiar la altura de su vehículo.","Siempre hay avisos señalizados en las zonas de poca altura libre."]},{"n":30,"section":"General Knowledge Test","en":"The purpose of a retarder is to:","es":"El propósito de un retardador es:","optsEn":["Apply extra braking power to the non-drive axles.","Help prevent skids and reduce brake wear.","Help slow the vehicle while driving and reduce brake wear."],"optsEs":["Aplicar potencia de frenado adicional a los ejes no motrices.","Ayudar a evitar derrapes y reducir el desgaste de los frenos.","Ayudar a frenar el vehículo mientras conduce y reducir el desgaste de los frenos."]},{"n":31,"section":"General Knowledge Test","en":"When hydraulic brakes fail, the system won't build up pressure and the brake pedal will feel spongy or go to the floor. What action should you take?","es":"Cuando fallan los frenos hidráulicos, el sistema no genera presión y el pedal se siente esponjoso o se va hasta el piso. ¿Qué debe hacer?","optsEn":["Push down on the brake pedal as hard as you can.","Pump the brake pedal to generate pressure.","Put the vehicle in neutral and set the parking brake."],"optsEs":["Pisar el pedal del freno con toda la fuerza posible.","Bombear el pedal del freno para generar presión.","Poner el vehículo en neutral y aplicar el freno de estacionamiento."]},{"n":32,"section":"General Knowledge Test","en":"Controlled braking:","es":"El frenado controlado:","optsEn":["Involves locking the wheels for short periods of time.","Is used to keep a vehicle in a straight line when braking.","Should only be used with hydraulic brakes."],"optsEs":["Implica bloquear las ruedas por periodos cortos de tiempo.","Se usa para mantener el vehículo en línea recta al frenar.","Solo debe usarse con frenos hidráulicos."]}]},"10":{"folio":19,"section":"General Knowledge Test","questions":[{"n":46,"section":"General Knowledge Test","en":"What should you do when your vehicle hydroplanes?","es":"¿Qué debe hacer cuando su vehículo hidroplanea?","optsEn":["Start stab braking.","Release the accelerator.","Accelerate slightly."],"optsEs":["Comenzar el frenado tipo “stab”.","Soltar el acelerador.","Acelerar ligeramente."]},{"n":48,"section":"General Knowledge Test","en":"When you are passing another vehicle, pedestrian, or bicyclist, you should assume that they:","es":"Cuando rebasa a otro vehículo, peatón o ciclista, debe suponer que:","optsEn":["May move into your traffic lane.","Know you want to pass.","See your vehicle."],"optsEs":["Podrían meterse en su carril.","Saben que usted quiere rebasar.","Ven su vehículo."]},{"n":49,"section":"General Knowledge Test","en":"Which of these systems should receive extra attention during a winter weather inspection?","es":"¿A cuál de estos sistemas debe prestar atención adicional en una inspección de invierno?","optsEn":["Exhaust.","Suspension.","Steering."],"optsEs":["El escape.","La suspensión.","La dirección."]},{"n":50,"section":"General Knowledge Test","en":"You are driving on a straight, level highway at 50 mph with no vehicles in front of you. Suddenly a tire blows out on your vehicle. What should you do first?","es":"Conduce por una carretera recta y plana a 50 mph sin vehículos delante. De repente revienta una llanta. ¿Qué debe hacer primero?","optsEn":["Stay off the brake until the vehicle has slowed down.","Begin light braking.","Begin emergency braking."],"optsEs":["No usar el freno hasta que el vehículo haya reducido la velocidad.","Comenzar a frenar suavemente.","Comenzar un frenado de emergencia."]}]},"11":{"folio":21,"section":"General Knowledge Test","questions":[{"n":11,"section":"General Knowledge Test","en":"Which of these systems should receive extra attention during a winter weather inspection?","es":"¿A cuál de estos sistemas debe prestar atención adicional en una inspección de invierno?","optsEn":["Suspension.","Steering.","Exhaust."],"optsEs":["La suspensión.","La dirección.","El escape."]},{"n":12,"section":"General Knowledge Test","en":"Which of these statements is true about hazardous materials?","es":"¿Cuál de estas afirmaciones es verdadera sobre los materiales peligrosos?","optsEn":["All hazardous materials present a health and safety threat.","All trucks with any amount of hazardous materials must display placards.","All public roads allow properly loaded trucks to carry hazardous materials."],"optsEs":["Todos los materiales peligrosos representan una amenaza para la salud y la seguridad.","Todo camión con cualquier cantidad de material peligroso debe llevar rótulos.","Todas las vías públicas permiten que camiones bien cargados transporten materiales peligrosos."]},{"n":13,"section":"General Knowledge Test","en":"The braking effect of the engine is greatest when the engine is ____ the governed RPMs and the transmission is in the ____ gears.","es":"El efecto de frenado del motor es mayor cuando el motor está ____ las RPM reguladas y la transmisión está en las marchas ____.","optsEn":["Above, lower.","Below, higher.","Near, lower."],"optsEs":["Por encima de, más bajas.","Por debajo de, más altas.","Cerca de, más bajas."]},{"n":14,"section":"General Knowledge Test","en":"CDL medical certificates must be renewed every:","es":"Los certificados médicos CDL deben renovarse cada:","optsEn":["Year.","Two years.","Four years."],"optsEs":["Año.","Dos años.","Cuatro años."]},{"n":15,"section":"General Knowledge Test","en":"Which of these is a good thing to do when you steer to avoid a crash?","es":"¿Cuál de estas es una buena práctica al girar para evitar un choque?","optsEn":["Don't turn the steering wheel any more than needed.","Avoid countersteering.","Apply the brakes while turning."],"optsEs":["No girar el volante más de lo necesario.","Evitar el contravolanteo.","Aplicar los frenos mientras gira."]},{"n":16,"section":"General Knowledge Test","en":"What is the first thing you should do if your brakes fail while driving downhill?","es":"¿Qué es lo primero que debe hacer si fallan los frenos mientras conduce cuesta abajo?","optsEn":["Call or radio for help.","Try to use your parking brake to stop.","Get off the road as soon as possible."],"optsEs":["Llamar o pedir ayuda por radio.","Intentar detenerse con el freno de estacionamiento.","Salir de la carretera lo antes posible."]},{"n":17,"section":"General Knowledge Test","en":"Which of these statements is true about double clutching and shifting?","es":"¿Cuál de estas afirmaciones es verdadera sobre el doble embrague y los cambios?","optsEn":["Double clutching should not be used when the road is slippery.","Double clutching should only be used with a heavy load.","You can use the tachometer to tell you when to shift."],"optsEs":["No debe usarse doble embrague cuando el camino está resbaloso.","El doble embrague solo debe usarse con carga pesada.","Puede usar el tacómetro para saber cuándo cambiar de marcha."]},{"n":18,"section":"General Knowledge Test","en":"When you drive in the mountains, you will have to use lower gears to drive safely down grades. Which of these does not affect your choice of gears?","es":"Al conducir en montaña deberá usar marchas más bajas para bajar pendientes con seguridad. ¿Cuál de estos no afecta su elección de marcha?","optsEn":["Weight of the load.","Tire tread type.","Length of the grade."],"optsEs":["El peso de la carga.","El tipo de dibujo de la llanta.","La longitud de la pendiente."]},{"n":19,"section":"General Knowledge Test","en":"You are checking your brakes and suspension system during a pre-trip inspection. Which of these statements is true?","es":"Está revisando los frenos y el sistema de suspensión durante una inspección previa al viaje. ¿Cuál de estas afirmaciones es verdadera?","optsEn":["Just one missing leaf spring is not dangerous.","Cracked spring hangers that are still tight are not dangerous.","Brake shoes should not have oil, grease, or brake fluid on them."],"optsEs":["Que falte una sola hoja del muelle no es peligroso.","Los soportes del muelle agrietados pero aún apretados no son peligrosos.","Las zapatas de freno no deben tener aceite, grasa ni líquido de frenos."]},{"n":20,"section":"General Knowledge Test","en":"To avoid a crash, you had to drive onto the right shoulder. You are now driving at 40 mph on the shoulder. How should you move back onto the pavement?","es":"Para evitar un choque tuvo que salirse al acotamiento derecho. Ahora circula a 40 mph sobre el acotamiento. ¿Cómo debe volver al pavimento?","optsEn":["Brake hard to slow the vehicle, then steer sharply onto the pavement when it is safe.","Keep moving at your present speed and steer very gently back onto the pavement when it is safe.","If the shoulder is clear, stay on it until your vehicle comes to a stop. Then move back onto the pavement when it is safe."],"optsEs":["Frenar fuerte para reducir la velocidad y luego girar bruscamente al pavimento cuando sea seguro.","Mantener la velocidad actual y volver al pavimento girando muy suavemente cuando sea seguro.","Si el acotamiento está despejado, permanecer en él hasta detenerse por completo y luego volver al pavimento cuando sea seguro."]},{"n":21,"section":"General Knowledge Test","en":"When do strong winds affect driving the most?","es":"¿Cuándo afectan más los vientos fuertes a la conducción?","optsEn":["On open highways.","On bridges or overpasses.","When exiting tunnels."],"optsEs":["En carreteras abiertas.","En puentes o pasos elevados.","Al salir de túneles."]}]},"12":{"folio":23,"section":"General Knowledge Test","questions":[{"n":34,"section":"General Knowledge Test","en":"Whenever you double your speed, it will take about ____ times as much distance to stop.","es":"Cada vez que duplica su velocidad, necesitará aproximadamente ____ veces más distancia para detenerse.","optsEn":["Two.","Three.","Four."],"optsEs":["Dos.","Tres.","Cuatro."]},{"n":35,"section":"General Knowledge Test","en":"If a straight vehicle (no trailer or articulation) goes into a front-wheel skid, it will:","es":"Si un vehículo rígido (sin remolque ni articulación) entra en un derrape de las ruedas delanteras:","optsEn":["Slide sideways and spin out.","Travel straight ahead even if you turn the steering wheel.","Travel straight ahead until you turn the steering wheel."],"optsEs":["Se deslizará de lado y girará sin control.","Seguirá derecho aunque gire el volante.","Seguirá derecho hasta que gire el volante."]},{"n":36,"section":"General Knowledge Test","en":"Optional safety equipment may include emergency phone numbers, tire chains, and:","es":"El equipo de seguridad opcional puede incluir números de teléfono de emergencia, cadenas para llantas y:","optsEn":["Tire changing equipment.","Red reflective triangles.","Charged fire extinguisher."],"optsEs":["Equipo para cambiar llantas.","Triángulos reflectantes rojos.","Un extintor cargado."]},{"n":37,"section":"General Knowledge Test","en":"If you have a heavy load that is slowing you down on an upgrade, you should:","es":"Si lleva una carga pesada que lo hace ir más lento en una subida, debe:","optsEn":["Exit the road until traffic is lighter.","Drive on the shoulder so others can pass easily.","Shift into a lower gear."],"optsEs":["Salir de la carretera hasta que haya menos tráfico.","Circular por el acotamiento para que los demás rebasen con facilidad.","Cambiar a una marcha más baja."]},{"n":38,"section":"General Knowledge Test","en":"You are stopped. You want to start driving uphill. You should:","es":"Está detenido. Quiere comenzar a conducir cuesta arriba. Debe:","optsEn":["Partly engage the clutch and then release the parking brake.","Engage the clutch and accelerate quickly.","Keep the trailer brake hand valve applied until you reach 20 mph."],"optsEs":["Acoplar parcialmente el embrague y luego soltar el freno de estacionamiento.","Acoplar el embrague y acelerar rápidamente.","Mantener aplicada la válvula manual del freno del remolque hasta llegar a 20 mph."]},{"n":39,"section":"General Knowledge Test","en":"How many missing or broken leaves in any leaf spring will cause a commercial vehicle to be placed out of service?","es":"¿Cuántas hojas faltantes o rotas en un muelle de hojas hacen que un vehículo comercial quede fuera de servicio?","optsEn":["One-fourth of the total number.","One-third of the total number.","One-half of the total number."],"optsEs":["Un cuarto del total.","Un tercio del total.","La mitad del total."]},{"n":40,"section":"General Knowledge Test","en":"The Commercial Driver Handbook suggests several things to do when you pass a vehicle. Which of these is not one of them?","es":"El Manual del Conductor Comercial sugiere varias cosas al rebasar un vehículo. ¿Cuál de estas no es una de ellas?","optsEn":["Lightly tap on your horn, if needed.","At night, turn on your high beams while you pass the vehicle.","Assume the other driver does not see you."],"optsEs":["Tocar el claxon suavemente si es necesario.","De noche, encender las luces altas mientras rebasa el vehículo.","Suponer que el otro conductor no lo ve."]},{"n":41,"section":"General Knowledge Test","en":"Controlled braking:","es":"El frenado controlado:","optsEn":["Involves locking the wheels for short periods of time.","Is used to keep a vehicle in a straight line when braking.","Should only be used with hydraulic brakes."],"optsEs":["Implica bloquear las ruedas por periodos cortos de tiempo.","Se usa para mantener el vehículo en línea recta al frenar.","Solo debe usarse con frenos hidráulicos."]},{"n":42,"section":"General Knowledge Test","en":"You wish to turn right from a two-lane, two-way street into another. Your vehicle is so long that you must swing wide to complete the turn. Which of these figures shows how you should make the turn?","es":"Desea girar a la derecha de una calle de dos carriles y doble sentido hacia otra. Su vehículo es tan largo que debe abrirse para completar el giro. ¿Cuál de estas figuras muestra cómo debe hacer el giro?","optsEn":["Figure A.","Figure B.","Figure C."],"optsEs":["Figura A.","Figura B.","Figura C."],"figure":true},{"n":43,"section":"General Knowledge Test","en":"Which of these is not proper use of vehicle lights?","es":"¿Cuál de estos no es un uso adecuado de las luces del vehículo?","optsEn":["Turning on your headlights during the day when visibility is reduced.","Flashing your brake lights to warn someone behind you that you are slowing down.","Flashing your brake lights to stop someone tailgating."],"optsEs":["Encender los faros durante el día cuando la visibilidad es reducida.","Destellar las luces de freno para advertir a quien viene detrás que está desacelerando.","Destellar las luces de freno para detener a alguien que le sigue muy de cerca."]}]},"13":{"folio":25,"section":"Air Brake Test","questions":[{"n":5,"section":"Air Brake Test","en":"If your truck or bus has dual parking control valves, you can use pressure from a separate tank to:","es":"Si su camión o autobús tiene válvulas dobles de control de estacionamiento, puede usar la presión de un tanque separado para:","optsEn":["Release spring emergency/parking brakes to move a short distance.","Apply more brake pressure if the main tank is getting low.","Balance the service brake system whenever you are parked."],"optsEs":["Liberar los frenos de resorte de emergencia o estacionamiento para avanzar una distancia corta.","Aplicar más presión de freno si el tanque principal se está quedando bajo.","Equilibrar el sistema de frenos de servicio siempre que esté estacionado."]},{"n":6,"section":"Air Brake Test","en":"The driver must be able to see a low air pressure warning which comes on before pressure in the service air tanks falls below ____ psi.","es":"El conductor debe poder ver una advertencia de baja presión que se enciende antes de que la presión en los tanques de servicio caiga por debajo de ____ psi.","optsEn":["40.","60.","80."],"optsEs":["40.","60.","80."]},{"n":7,"section":"Air Brake Test","en":"Excessive use of the service brakes results in overheating, which can lead to:","es":"El uso excesivo de los frenos de servicio provoca sobrecalentamiento, que puede causar:","optsEn":["Improper adjustment of the S-cam.","Increased contact between the brake drums and brake linings.","Expansion of the brake drums."],"optsEs":["Ajuste incorrecto de la leva en S.","Mayor contacto entre los tambores y las balatas.","Expansión de los tambores de freno."]},{"n":8,"section":"Air Brake Test","en":"Total stopping distance for vehicles with air brakes is longer than that for vehicles with hydraulic brakes due to ____ distance.","es":"La distancia total de frenado en vehículos con frenos de aire es mayor que en los de frenos hidráulicos debido a la distancia de ____.","optsEn":["Brake lag.","Reaction.","Effective braking."],"optsEs":["Retraso del freno.","Reacción.","Frenado efectivo."]},{"n":9,"section":"Air Brake Test","en":"The proper method of braking when going down long and/or steep grades, after selecting the proper gear, is to brake until your speed is about ____ miles per hour below your \"safe\" speed, then release your brakes.","es":"El método correcto de frenado en bajadas largas o empinadas, tras elegir la marcha adecuada, es frenar hasta que su velocidad esté unas ____ millas por hora por debajo de su velocidad “segura” y luego soltar los frenos.","optsEn":["5.","10.","15."],"optsEs":["5.","10.","15."]},{"n":10,"section":"Air Brake Test","en":"To check the free play of manual slack adjusters on S-cam brakes, you should park on level ground:","es":"Para comprobar el juego libre de los ajustadores manuales de holgura en frenos de leva en S, debe estacionar en terreno plano:","optsEn":["Chock the wheels and turn off the parking brakes.","With the parking brake and then apply the service brake.","And drain off air pressure before adjusting vehicle movement."],"optsEs":["Calzar las ruedas y liberar los frenos de estacionamiento.","Con el freno de estacionamiento puesto y luego aplicar el freno de servicio.","Y purgar la presión de aire antes de ajustar el movimiento del vehículo."]},{"n":11,"section":"Air Brake Test","en":"Before driving a truck or bus with a dual air brake system, the pressure in each system should be at least ____ psi.","es":"Antes de conducir un camión o autobús con sistema doble de frenos de aire, la presión en cada sistema debe ser de al menos ____ psi.","optsEn":["80.","100.","120."],"optsEs":["80.","100.","120."]},{"n":12,"section":"Air Brake Test","en":"What is emergency stab braking?","es":"¿Qué es el frenado de emergencia tipo “stab”?","optsEn":["Press hard on the brake pedal and apply full hand valve until you stop.","Use light steady pressure on the brake pedal.","Brake as hard as you can, release the brakes when the wheels lock, and reapply the brakes again when the wheels start rolling."],"optsEs":["Pisar fuerte el pedal y aplicar la válvula manual a fondo hasta detenerse.","Aplicar presión ligera y constante sobre el pedal del freno.","Frenar con toda la fuerza posible, soltar los frenos cuando las ruedas se bloqueen y volver a aplicarlos cuando las ruedas empiecen a rodar."]},{"n":13,"section":"Air Brake Test","en":"The parking or emergency brake on a heavy vehicle can only be held in position by something that cannot leak away, like:","es":"El freno de estacionamiento o de emergencia de un vehículo pesado solo puede mantenerse aplicado por algo que no pueda fugarse, como:","optsEn":["Spring pressure.","Air pressure.","Hydraulic pressure."],"optsEs":["La presión de un resorte.","La presión de aire.","La presión hidráulica."]},{"n":14,"section":"Air Brake Test","en":"Which of these is not a proper time to apply the parking brake:","es":"¿Cuál de estos no es un momento adecuado para aplicar el freno de estacionamiento?","optsEn":["When you will only be stopped for less than one hour.","When you are going to test the parking brake.","When you come down a steep grade and your brakes are very hot."],"optsEs":["Cuando solo va a estar detenido menos de una hora.","Cuando va a probar el freno de estacionamiento.","Cuando acaba de bajar una pendiente empinada y los frenos están muy calientes."]},{"n":15,"section":"Air Brake Test","en":"Some air brake systems have an alcohol evaporator. What may happen if you don't keep the unit filled with alcohol?","es":"Algunos sistemas de frenos de aire tienen un evaporador de alcohol. ¿Qué puede pasar si no mantiene la unidad llena de alcohol?","optsEn":["The S-cam may not rotate back when you release the brake pedal.","Ice may form in the air storage tanks and cause the brakes to fail.","Ice may form on the brake drums and warp them."],"optsEs":["La leva en S podría no regresar al soltar el pedal del freno.","Puede formarse hielo en los tanques de aire y provocar la falla de los frenos.","Puede formarse hielo en los tambores y deformarlos."]}]},"14":{"folio":27,"section":"General Knowledge Test","questions":[{"n":1,"section":"General Knowledge Test","en":"On which fires can you use water?","es":"¿En qué tipo de incendios puede usar agua?","optsEn":["Electric.","Gasoline.","Tires."],"optsEs":["Eléctricos.","De gasolina.","De llantas."]},{"n":2,"section":"General Knowledge Test","en":"Truck escape ramps:","es":"Las rampas de escape para camiones:","optsEn":["Help avoid damage to vehicles.","Cannot be used by certain types of heavy vehicles.","Are not for buses."],"optsEs":["Ayudan a evitar daños a los vehículos.","No pueden usarlas ciertos tipos de vehículos pesados.","No son para autobuses."]},{"n":3,"section":"General Knowledge Test","en":"What should you do if you are unsure whether you have enough overhead clearance?","es":"¿Qué debe hacer si no está seguro de tener suficiente espacio libre por encima?","optsEn":["Slow down slightly and try to drive under the object.","Find another route that will not require driving under the object.","Estimate the height of an overhead object if it is not posted."],"optsEs":["Reducir un poco la velocidad e intentar pasar por debajo del objeto.","Buscar otra ruta que no requiera pasar por debajo del objeto.","Estimar la altura del objeto elevado si no está señalizada."]},{"n":4,"section":"General Knowledge Test","en":"Most serious skids result from:","es":"La mayoría de los derrapes graves son consecuencia de:","optsEn":["Turning too sharply.","Decelerating too fast.","Driving too fast for conditions."],"optsEs":["Girar demasiado cerrado.","Desacelerar demasiado rápido.","Conducir demasiado rápido para las condiciones."]},{"n":5,"section":"General Knowledge Test","en":"Why is a broken exhaust system dangerous?","es":"¿Por qué es peligroso un sistema de escape roto?","optsEn":["Poisonous fumes could enter the cab or sleeper berth.","You could pollute the air with exhaust smoke.","Loud noise could damage the driver's ears."],"optsEs":["Gases venenosos podrían entrar a la cabina o al camarote.","Podría contaminar el aire con humo del escape.","El ruido fuerte podría dañar los oídos del conductor."]},{"n":6,"section":"General Knowledge Test","en":"You are driving a new truck with a manual transmission. What gear will you probably have to use to take a long, steep, downhill grade?","es":"Conduce un camión nuevo con transmisión manual. ¿Qué marcha tendrá que usar probablemente para bajar una pendiente larga y empinada?","optsEn":["The same gear you would use to climb the hill.","A higher gear than you would use to climb the hill.","A lower gear than you would use to climb the hill."],"optsEs":["La misma marcha que usaría para subir la cuesta.","Una marcha más alta que la que usaría para subir la cuesta.","Una marcha más baja que la que usaría para subir la cuesta."]},{"n":7,"section":"General Knowledge Test","en":"For a first offense of driving a commercial vehicle under the influence of alcohol or drugs, you will lose your CDL for at least:","es":"Por una primera infracción de conducir un vehículo comercial bajo los efectos del alcohol o las drogas, perderá su CDL por al menos:","optsEn":["6 months.","2 years.","1 year."],"optsEs":["6 meses.","2 años.","1 año."]},{"n":8,"section":"General Knowledge Test","en":"You are performing a pre-trip inspection on your brakes and suspension system. Which of these statements is true?","es":"Está realizando una inspección previa al viaje de los frenos y la suspensión. ¿Cuál de estas afirmaciones es verdadera?","optsEn":["Just one missing leaf spring is not dangerous.","Spring hangers that are cracked but still tight are not dangerous.","Brake shoes should not have oil, grease or brake fluid on them."],"optsEs":["Que falte una sola hoja del muelle no es peligroso.","Los soportes del muelle agrietados pero aún apretados no son peligrosos.","Las zapatas de freno no deben tener aceite, grasa ni líquido de frenos."]},{"n":9,"section":"General Knowledge Test","en":"Which of these statements is true about staying alert to drive?","es":"¿Cuál de estas afirmaciones es verdadera sobre mantenerse alerta al conducir?","optsEn":["A half-hour coffee break will do more to keep you alert than a half-hour nap.","If you must stop, pull over to the side of the road for a short nap.","Sleep is the only thing that can overcome fatigue."],"optsEs":["Media hora de café lo mantendrá más alerta que media hora de siesta.","Si debe detenerse, oríllese a un costado del camino para una siesta corta.","El sueño es lo único que puede vencer la fatiga."]},{"n":10,"section":"General Knowledge Test","en":"CDL medical certificates must be renewed every:","es":"Los certificados médicos CDL deben renovarse cada:","optsEn":["Year.","Two years.","Four years."],"optsEs":["Año.","Dos años.","Cuatro años."]}]}};
